// ══════════════════════════════════════
function WhistleblowerSVG({ lang }) {
  const [step, setStep] = useState(0);
  const steps = [
    { icon:"🤫", color:C.red,
      label:{fr:"Marin témoin d'une violation",en:"Seafarer witnesses a violation",es:"Marinero testigo de una infracción",pt:"Marinheiro testemunha uma violação"},
      desc:{fr:"Tu travailles sur un navire et tu constates :\n• Magic pipe · ORB falsifié\n• Rejet illégal d'hydrocarbures\n• Violation MARPOL grave\nTu as le DROIT et la PROTECTION de signaler",en:"You work on a vessel and observe:\n• Magic pipe · False ORB\n• Illegal oil discharge\n• Serious MARPOL violation\nYou have the RIGHT and PROTECTION to report",es:"Trabajas en un buque y constatas:\n• Magic pipe · ORB falsificado\n• Vertido ilegal de hidrocarburos\n• Infracción grave de MARPOL\nTienes el DERECHO y la PROTECCIÓN de denunciar",pt:"Traballas num navio e constatas:\n• Magic pipe · ORB falsificado\n• Descarga ilegal de hidrocarbonetos\n• Violação grave do MARPOL\nTens o DIREITO e a PROTEÇÃO de denunciar"}},
    { icon:"📞", color:C.orange,
      label:{fr:"Contact USCG / autorités",en:"Contact USCG / authorities",es:"Contactar USCG / autoridades",pt:"Contactar USCG / autoridades"},
      desc:{fr:"USCG (USA) : numéro gratuit 1-800-424-8802\nAuto-saisine dans tout port américain\nIMO : mécanisme de signalement confidentiel\nAutorités portuaires locales\n→ Les informations peuvent être anonymes\n→ Protection contre les représailles garantie",en:"USCG (USA): free number 1-800-424-8802\nSelf-referral at any US port\nIMO: confidential reporting mechanism\nLocal port authorities\n→ Information can be anonymous\n→ Protection against retaliation guaranteed",es:"USCG (EE.UU.): número gratuito 1-800-424-8802\nDenuncia voluntaria en cualquier puerto americano\nOMI: mecanismo de denuncia confidencial\nAutoridades portuarias locales\n→ La información puede ser anónima\n→ Protección contra represalias garantizada",pt:"USCG (EUA): número gratuito 1-800-424-8802\nAuto-denúncia em qualquer porto americano\nIMO: mecanismo de denúncia confidencial\nAutoridades portuárias locais\n→ A informação pode ser anónima\n→ Proteção contra represálias garantida"}},
    { icon:"🔍", color:C.blue2,
      label:{fr:"Enquête USCG",en:"USCG investigation",es:"Investigación USCG",pt:"Investigação USCG"},
      desc:{fr:"Inspection approfondie du navire\nSaisie du journal machine (ORB)\nAnalyse des tuyauteries\nAudition de l'équipage\nPrélèvements eaux de cale\nSi preuves suffisantes → arrestation navire",en:"In-depth vessel inspection\nSeizure of engine log (ORB)\nPiping analysis\nCrew hearings\nBilge water sampling\nIf sufficient evidence → vessel arrest",es:"Inspección profunda del buque\nIncautación del diario de máquinas (ORB)\nAnálisis de tuberías\nDeclaraciones de la tripulación\nMuestras agua de sentina\nSi pruebas suficientes → arresto buque",pt:"Inspeção aprofundada do navio\nApreensão do diário de máquinas (ORB)\nAnálise de tubagens\nAudição da tripulação\nAmostras de água de porão\nSe provas suficientes → arresto do navio"}},
    { icon:"⚖️", color:C.purple,
      label:{fr:"Procédure judiciaire",en:"Legal proceedings",es:"Proceso judicial",pt:"Processo judicial"},
      desc:{fr:"Inculpation compagnie + officiers responsables\nChefs d'accusation : 18 USC §1505 (faux registres)\nProcès fédéral devant jury\nNégociation possible (plea deal)\nCondamnation : prison + amendes\nRetrait certificats officiels",en:"Indictment of company + responsible officers\nCharges: 18 USC §1505 (false records)\nFederal trial before jury\nPlea deal possible\nSentencing: prison + fines\nOfficer certificate revocation",es:"Acusación compañía + oficiales responsables\nCargos: 18 USC §1505 (registros falsos)\nJuicio federal ante jurado\nAcuerdo de culpabilidad posible\nCondena: prisión + multas\nRevocación certificados de oficiales",pt:"Acusação companhia + oficiais responsáveis\nAcusações: 18 USC §1505 (registos falsos)\nJulgamento federal perante júri\nAcordo de culpa possível\nCondenação: prisão + multas\nRevogação certificados de oficiais"}},
    { icon:"💰", color:C.green,
      label:{fr:"Récompense whistleblower",en:"Whistleblower reward",es:"Recompensa whistleblower",pt:"Recompensa whistleblower"},
      desc:{fr:"Programme USA (False Claims Act)\nRécompense : jusqu'à 30% des amendes collectées\nMaximum historique : $3,7 millions\nCas typique : $100 000 - $500 000\nProtection totale contre représailles\nImmunité judiciaire (si de bonne foi)\n→ Contacter un avocat maritime AVANT de signaler",en:"USA program (False Claims Act)\nReward: up to 30% of collected fines\nHistorical maximum: $3.7 million\nTypical case: $100,000 - $500,000\nFull protection against retaliation\nJudicial immunity (if good faith)\n→ Contact a maritime lawyer BEFORE reporting",es:"Programa EE.UU. (False Claims Act)\nRecompensa: hasta el 30% de las multas cobradas\nMáximo histórico: $3,7 millones\nCaso típico: $100.000 - $500.000\nProtección total contra represalias\nInmunidad judicial (si es de buena fe)\n→ Contactar a un abogado marítimo ANTES de denunciar",pt:"Programa EUA (False Claims Act)\nRecompensa: até 30% das multas cobradas\nMáximo histórico: $3,7 milhões\nCaso típico: $100.000 - $500.000\nProteção total contra represálias\nImunidade judicial (se de boa fé)\n→ Contactar um advogado marítimo ANTES de denunciar"}},
  ];
  const s = steps[step];
  return (
    <div>
      <div style={{display:"flex",gap:4,marginBottom:10}}>
        {steps.map((st,i)=>(
          <button key={i} onClick={()=>setStep(i)} style={{
            flex:1,padding:"6px 2px",borderRadius:8,cursor:"pointer",
            background:step===i?`${st.color}22`:"rgba(255,255,255,0.04)",
            border:`1.5px solid ${step===i?st.color:"rgba(255,255,255,0.06)"}`,
            display:"flex",flexDirection:"column",alignItems:"center",gap:2,
          }}>
            <span style={{fontSize:14}}>{st.icon}</span>
            <div style={{fontSize:6,color:step===i?st.color:C.muted,fontWeight:700}}>{i+1}</div>
          </button>
        ))}
      </div>
      <div style={{padding:"12px",borderRadius:14,background:`${s.color}12`,border:`1.5px solid ${s.color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:13,fontWeight:700,color:s.color,marginBottom:8}}>{s.icon} {s.label[lang]||s.label.fr}</div>
        <div style={{fontSize:11,color:C.white,lineHeight:1.7,whiteSpace:"pre-line"}}>{s.desc[lang]||s.desc.fr}</div>
      </div>
      <div style={{display:"flex",gap:8,marginTop:8}}>
        <button onClick={()=>setStep(s=>Math.max(0,s-1))} disabled={step===0}
          style={{flex:1,padding:"8px",borderRadius:10,background:"rgba(255,255,255,0.06)",border:"1px solid rgba(255,255,255,0.1)",color:step===0?C.muted:C.white,cursor:step===0?"default":"pointer",fontSize:11}}>
          ◀ {lang==="fr"?"Précédent":"Previous"}
        </button>
        <button onClick={()=>setStep(s=>Math.min(4,s+1))} disabled={step===4}
          style={{flex:1,padding:"8px",borderRadius:10,background:step===4?"rgba(255,255,255,0.06)":`${steps[Math.min(4,step+1)].color}22`,border:`1px solid ${step===4?"rgba(255,255,255,0.1)":steps[Math.min(4,step+1)].color}`,color:C.white,cursor:step===4?"default":"pointer",fontSize:11,fontWeight:700}}>
          {lang==="fr"?"Suivant":"Next"} ▶
        </button>
      </div>
    </div>
  );
}

