function AccidentCase({ lang }) {
  const [exp,setExp]=useState(false);
  const d={
    fr:{title:"Affaire Princess Cruise Lines — USA (2016-2019)",teaser:"Compagnie maritime · Magic pipe · $40 millions amende · 5 ans probation · Scandale mondial",what:"La compagnie Princess Cruise Lines (groupe Carnival) est reconnue coupable d'avoir ordonné le rejet d'eaux huileuses directement en mer depuis plusieurs navires, de 2005 à 2013. Les machines comprenaient des 'magic pipes'. Les ORB étaient falsifiés. Un ingénieur britannique a tout révélé aux autorités américaines.",cause:"• Direction de la compagnie au courant et complice\n• Magic pipes sur plusieurs navires (pas un accident isolé)\n• ORB falsifiés de manière systématique\n• Pression des supérieurs sur les officiers pour frauder\n• Dissimulation aux enquêteurs pendant la procédure\n• Violation des conditions de probation (2017) → sanctions aggravées",lessons:"✓ Responsabilité remontant jusqu'à la direction de la compagnie\n✓ Programme whistleblower = efficace · l'ingénieur a tout déclenché\n✓ Récidive pendant probation = aggravation massive\n✓ Résultat : $40 millions d'amende totale (record mondial)\n✓ 5 ans de probation + auditeur indépendant permanent\n✓ Retraite du PDG · licenciements massifs",link:"🔗 Lien L2 MARPOL juridique : Cette affaire prouve que MARPOL n'est pas qu'un règlement technique. C'est un outil juridique puissant avec des conséquences pénales réelles pour les officiers ET les compagnies."},
    en:{title:"Princess Cruise Lines Case — USA (2016-2019)",teaser:"Shipping company · Magic pipe · $40 million fine · 5 years probation · Global scandal",what:"Princess Cruise Lines (Carnival group) is found guilty of ordering discharge of oily water directly at sea from multiple vessels, from 2005 to 2013. Machinery included 'magic pipes'. ORBs were falsified. A British engineer revealed everything to US authorities.",cause:"• Company management aware and complicit\n• Magic pipes on multiple vessels (not an isolated incident)\n• ORBs systematically falsified\n• Superior pressure on officers to commit fraud\n• Concealment from investigators during proceedings\n• Probation violation (2017) → enhanced sanctions",lessons:"✓ Liability extending to company management\n✓ Whistleblower program = effective · the engineer triggered everything\n✓ Recidivism during probation = massive aggravation\n✓ Result: $40 million total fine (world record)\n✓ 5 years probation + permanent independent auditor\n✓ CEO retirement · mass layoffs",link:"🔗 L2 MARPOL Legal Link: This case proves MARPOL is not just a technical regulation. It is a powerful legal tool with real criminal consequences for officers AND companies."},
    es:{title:"Caso Princess Cruise Lines — EE.UU. (2016-2019)",teaser:"Compañía marítima · Magic pipe · $40 millones de multa · 5 años de libertad condicional · Escándalo mundial",what:"Princess Cruise Lines (grupo Carnival) es declarada culpable de haber ordenado el vertido de aguas oleosas directamente al mar desde varios buques, de 2005 a 2013. Las máquinas incluían 'magic pipes'. Los ORB estaban falsificados. Un ingeniero británico reveló todo a las autoridades estadounidenses.",cause:"• Dirección de la compañía al corriente y cómplice\n• Magic pipes en varios buques (no un incidente aislado)\n• ORB falsificados de forma sistemática\n• Presión de superiores sobre los oficiales para cometer fraude\n• Ocultamiento a los investigadores\n• Violación de las condiciones de libertad condicional (2017)",lessons:"✓ Responsabilidad que llega hasta la dirección de la compañía\n✓ Programa whistleblower = eficaz · el ingeniero desencadenó todo\n✓ Reincidencia durante la libertad condicional = agravamiento masivo\n✓ Resultado: $40 millones de multa total (récord mundial)\n✓ 5 años de libertad condicional + auditor independiente permanente",link:"🔗 Vínculo L2: Este caso demuestra que MARPOL no es solo un reglamento técnico. Es una potente herramienta jurídica con consecuencias penales reales para los oficiales Y las compañías."},
    pt:{title:"Caso Princess Cruise Lines — EUA (2016-2019)",teaser:"Companhia marítima · Magic pipe · $40 milhões de multa · 5 anos de liberdade condicional · Escândalo mundial",what:"A Princess Cruise Lines (grupo Carnival) é declarada culpada de ter ordenado a descarga de águas oleosas diretamente no mar a partir de vários navios, de 2005 a 2013. As máquinas incluíam 'magic pipes'. Os ORB estavam falsificados. Um engenheiro britânico revelou tudo às autoridades americanas.",cause:"• Direção da companhia ciente e cúmplice\n• Magic pipes em vários navios (não um incidente isolado)\n• ORB falsificados de forma sistemática\n• Pressão dos superiores sobre os oficiais para cometer fraude\n• Ocultação aos investigadores\n• Violação das condições de liberdade condicional (2017)",lessons:"✓ Responsabilidade estendida à direção da companhia\n✓ Programa whistleblower = eficaz · o engenheiro desencadeou tudo\n✓ Reincidência durante liberdade condicional = agravamento massivo\n✓ Resultado: $40 milhões de multa total (recorde mundial)\n✓ 5 anos liberdade condicional + auditor independente permanente",link:"🔗 Vínculo L2: Este caso prova que o MARPOL não é apenas um regulamento técnico. É uma poderosa ferramenta jurídica com consequências penais reais para os oficiais E as companhias."},
  };
  const c=d[lang]||d.fr;
  return(
    <div style={{background:"rgba(192,57,43,0.08)",border:`1.5px solid ${C.red}44`,borderRadius:18,overflow:"hidden"}}>
      <div style={{padding:"14px 16px",cursor:"pointer"}} onClick={()=>setExp(v=>!v)}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{fontSize:22}}>⚖️</span>
          <div style={{flex:1}}><div style={{fontSize:13,fontWeight:700,color:C.red,marginBottom:2}}>{c.title}</div><div style={{fontSize:11,color:C.muted,lineHeight:1.4}}>{c.teaser}</div></div>
          <span style={{fontSize:14,color:C.muted}}>{exp?"▲":"▼"}</span>
        </div>
      </div>
      {exp&&<div style={{padding:"0 16px 16px"}}>
        <div style={{fontSize:12,color:C.white,lineHeight:1.7,marginBottom:10}}>{c.what}</div>
        <div style={{fontSize:11,color:C.red,fontWeight:700,marginBottom:5,fontFamily:"'Cinzel',serif"}}>CAUSES</div>
        <div style={{fontSize:12,color:C.white,lineHeight:1.7,whiteSpace:"pre-line",marginBottom:10}}>{c.cause}</div>
        <div style={{fontSize:11,color:C.green,fontWeight:700,marginBottom:5,fontFamily:"'Cinzel',serif"}}>{lang==="fr"?"LEÇONS":lang==="en"?"LESSONS":lang==="es"?"LECCIONES":"LIÇÕES"}</div>
        <div style={{fontSize:12,color:C.white,lineHeight:1.7,whiteSpace:"pre-line",marginBottom:10}}>{c.lessons}</div>
        <div style={{padding:"10px 12px",borderRadius:10,background:"rgba(201,146,42,0.1)",border:`1px solid ${C.gold}33`,fontSize:11,color:C.gold2,lineHeight:1.6}}>{c.link}</div>
      </div>}
    </div>
  );
}

// ══════════════════════════════════════
// EXERCISE
// ══════════════════════════════════════
function Exercise1({ lang, t }) {
  const [ans,setAns]=useState({q1:"",q2:"",q3:""});
  const [showC,setShowC]=useState(false);
  const qs={
    fr:[
      {id:"q1",q:"Quel article de l'UNCLOS donne le droit au Port State Control d'inspecter les navires étrangers pour violations MARPOL ?",correct:"218"},
      {id:"q2",q:"Quelle loi américaine permet au whistleblower de recevoir jusqu'à 30% des amendes collectées ?",correct:"False Claims Act"},
      {id:"q3",q:"Dans l'affaire Princess Cruise Lines, quel était le montant total de l'amende record ?\n(Répondre : ex. $40 millions)",correct:"40 millions"},
    ],
    en:[
      {id:"q1",q:"Which UNCLOS article gives Port State Control the right to inspect foreign vessels for MARPOL violations?",correct:"218"},
      {id:"q2",q:"What US law allows the whistleblower to receive up to 30% of collected fines?",correct:"False Claims Act"},
      {id:"q3",q:"In the Princess Cruise Lines case, what was the total record fine amount?\n(Answer: e.g. $40 million)",correct:"40 million"},
    ],
    es:[
      {id:"q1",q:"¿Qué artículo de la CONVEMAR da derecho al PSC a inspeccionar buques extranjeros por infracciones MARPOL?",correct:"218"},
      {id:"q2",q:"¿Qué ley estadounidense permite al whistleblower recibir hasta el 30% de las multas cobradas?",correct:"False Claims Act"},
      {id:"q3",q:"En el caso Princess Cruise Lines, ¿cuál fue el importe total de la multa récord?\n(Responder: ej. $40 millones)",correct:"40 millones"},
    ],
    pt:[
      {id:"q1",q:"Que artigo da UNCLOS dá ao PSC o direito de inspecionar navios estrangeiros por violações MARPOL?",correct:"218"},
      {id:"q2",q:"Que lei americana permite ao whistleblower receber até 30% das multas cobradas?",correct:"False Claims Act"},
      {id:"q3",q:"No caso Princess Cruise Lines, qual foi o valor total da multa recorde?\n(Responder: ex. $40 milhões)",correct:"40 milhões"},
    ],
  };
  const list=qs[lang]||qs.fr;
  const chk=(q,val)=>{
    const v=val.trim().toLowerCase();
    const c=q.correct.toLowerCase();
    return v===c||v.includes(c.split(" ")[0])||v.includes("218")||v.includes("false")||v.includes("40");
  };
  return(
    <div>
      <div style={{background:"rgba(0,0,0,0.4)",borderRadius:12,padding:"10px 12px",marginBottom:12,border:`1px solid ${C.red}44`,fontSize:11,color:C.gold2,lineHeight:1.6}}>
        {lang==="fr"?"💡 Rappels : UNCLOS Art.218 · False Claims Act · Princess Cruise $40M"
        :lang==="en"?"💡 Reminders: UNCLOS Art.218 · False Claims Act · Princess Cruise $40M"
        :lang==="es"?"💡 Recordatorios: CONVEMAR Art.218 · False Claims Act · Princess Cruise $40M"
        :"💡 Lembretes: UNCLOS Art.218 · False Claims Act · Princess Cruise $40M"}
      </div>
      {list.map((q,i)=>(
        <div key={q.id} style={{marginBottom:12}}>
          <div style={{fontSize:12,color:C.white,marginBottom:6,lineHeight:1.5,whiteSpace:"pre-line",fontWeight:600}}>{i+1}. {q.q}</div>
          <input type="text" value={ans[q.id]} onChange={e=>setAns(a=>({...a,[q.id]:e.target.value}))} placeholder="?"
            style={{width:"100%",padding:"10px",borderRadius:10,background:"rgba(255,255,255,0.07)",border:`1px solid ${showC?(chk(q,ans[q.id])?C.green:C.red):C.border}`,color:C.white,fontSize:14,fontFamily:"monospace",fontWeight:700,textAlign:"center",boxSizing:"border-box"}}/>
          {showC&&<div style={{fontSize:11,marginTop:4,fontWeight:600,color:chk(q,ans[q.id])?C.green:C.red}}>{chk(q,ans[q.id])?"✓":`✗ → ${q.correct}`}</div>}
        </div>
      ))}
      {showC&&<div style={{padding:"12px",borderRadius:12,background:"rgba(30,138,74,0.1)",border:`1px solid ${C.green}44`,fontSize:11,color:C.white,lineHeight:1.7,marginBottom:10}}>
        {lang==="fr"?"✅ Q1: Article 218 UNCLOS (droit d'enquête Port State Control)\n✅ Q2: False Claims Act (loi fédérale USA · jusqu'à 30% des amendes)\n✅ Q3: $40 millions (record mondial · Princess Cruise Lines 2016-2019)"
        :lang==="en"?"✅ Q1: UNCLOS Article 218 (Port State Control right of investigation)\n✅ Q2: False Claims Act (US federal law · up to 30% of fines)\n✅ Q3: $40 million (world record · Princess Cruise Lines 2016-2019)"
        :"✅ Q1: Art.218 CONVEMAR · Q2: False Claims Act · Q3: $40 millones"}
      </div>}
      <button onClick={()=>setShowC(v=>!v)} style={{width:"100%",padding:"11px 0",borderRadius:12,background:showC?"rgba(30,138,74,0.2)":"rgba(201,146,42,0.15)",border:`1px solid ${showC?C.green:C.gold}44`,color:showC?C.green:C.gold2,fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:"'Cinzel',serif"}}>
        {showC?t.hideCorr:t.showCorr}
      </button>
    </div>
  );
}


