const BANK = {
  fr:[
    {q:"Qu'est-ce que le 'droit de poursuite' (hot pursuit) en droit maritime ?",opts:["Un droit de chasse","Droit d'un État côtier de poursuivre en haute mer un navire étranger qui a violé ses lois dans ses eaux — doit être immédiat et continu","Un droit commercial maritime","Un type de procédure judiciaire"],correct:1,expl:"Droit de poursuite (hot pursuit) = UNCLOS Article 111. L'État côtier peut poursuivre un navire étranger jusque en haute mer si : la poursuite commence dans ses eaux (territoriales, ZEE, plateau continental), elle est immédiate et continue, et elle cesse si le navire entre dans les eaux d'un État tiers. Clé : CONTINUITÉ de la poursuite."},
    {q:"Qu'est-ce que le Fonds IOPC (International Oil Pollution Compensation Fund) ?",opts:["Un fonds d'assurance navire","Fonds international pour indemniser les victimes de pollution pétrolière maritime — alimenté par les importateurs de pétrole","Un fonds OMI pour les armateurs","Un fonds de recherche maritime"],correct:1,expl:"IOPC Fund = Fonds International d'Indemnisation pour les Dommages dus à la Pollution par les Hydrocarbures. Créé par Convention 1971, révisé 1992. Indemnise les États côtiers et particuliers victimes de déversements. Alimenté par contributions des importateurs de pétrole (pas les armateurs). Plafond d'indemnisation : environ $1,1 milliard. Complémentaire à la Convention CLC."},
    {q:"Qu'est-ce que la Convention CLC (Civil Liability Convention) ?",opts:["Une convention sur les équipages","Convention sur la responsabilité civile du propriétaire du navire pour la pollution par hydrocarbures — responsabilité objective + assurance P&I obligatoire","Une convention de travail maritime","Une convention sur les épaves"],correct:1,expl:"CLC = Convention sur la responsabilité civile pour les dommages dus à la pollution par les hydrocarbures (1969, révisée 1992). Responsabilité OBJECTIVE du propriétaire (pas besoin de prouver la faute). Assurance P&I obligatoire (Certificate of Insurance). Plafond de responsabilité selon tonnage. Complémentée par le Fonds IOPC pour les dommages dépassant le plafond."},
    {q:"Qu'est-ce qu'un 'club P&I' (Protection and Indemnity) en droit maritime ?",opts:["Un club de navigation de plaisance","Mutuelle d'assurance maritime couvrant la responsabilité civile du navire : pollution, dommages tiers, abandon d'équipage","Un type de certification navale","Un syndicat d'armateurs"],correct:1,expl:"P&I Club = Protection and Indemnity Club. Mutuelle d'assurance maritime créée par les armateurs au XIXe siècle. Couvre : responsabilité pollution (MARPOL/CLC), dommages aux tiers, abandonnement d'équipage (MLC), créances salariales, sauvetage. Les 13 clubs P&I du International Group couvrent 90% de la flotte mondiale. Certificat CLC = délivré par le P&I Club."},
    {q:"Qu'est-ce que la responsabilité 'objective' en droit maritime de la pollution ?",opts:["Une responsabilité basée sur la faute prouvée","Responsabilité engagée sans avoir à prouver la faute du propriétaire — suffit de prouver le dommage et le lien de causalité avec le navire","Une responsabilité partagée entre armateurs","Une responsabilité uniquement pénale"],correct:1,expl:"Responsabilité objective (strict liability) = responsabilité sans faute. En matière de pollution maritime (CLC, OPRC), il suffit de prouver : 1) qu'il y a eu dommage par pollution, 2) que le navire identifié est la source. Pas besoin de prouver la négligence ou la faute du propriétaire. Exception : force majeure (guerre, phénomène naturel exceptionnel). Garantit une indemnisation rapide des victimes."},
    {q:"Quelle est la différence entre infraction MARPOL et crime pénal ?",opts:["Aucune différence","Infraction MARPOL = violation administrative (amende) · Crime pénal = infraction intentionnelle ou par négligence grave (prison possible)","Infraction MARPOL = plus grave que crime pénal","Seuls les crimes pénaux concernent les marins"],correct:1,expl:"Distinction clé : Infraction MARPOL = peut être administrative (amende PSC, immobilisation navire). Crime pénal = quand il y a intention de frauder (magic pipe, faux ORB) ou négligence grave (non-notification déversement). USA : faux ORB = crime fédéral (18 USC §1505) → prison. France/UE : déversement volontaire = crime maritime → prison. La falsification des registres transforme une infraction en crime."},
    {q:"Qu'est-ce que la 'compétence universelle' appliquée à MARPOL ?",opts:["L'OMI peut poursuivre n'importe quel navire","Certains États étendent leur juridiction aux violations MARPOL commises n'importe où dans le monde — basée sur les effets","La COLREG s'applique partout","Chaque État a le même droit"],correct:1,expl:"Compétence universelle appliquée à MARPOL = certains États (USA notamment) étendent leurs poursuites pénales aux violations commises en haute mer par des navires étrangers si les effets se font sentir dans leurs eaux ou si le navire touche leurs ports. Basée sur la doctrine des 'effets' (effects doctrine). Fondement de la jurisprudence USCG contre les compagnies étrangères."},
    {q:"Qu'est-ce que la 'piercing the corporate veil' (levée du voile social) en droit maritime ?",opts:["Un type d'audit","Possibilité pour les tribunaux d'ignorer la personnalité juridique d'une société pour tenir ses dirigeants personnellement responsables — en cas de fraude délibérée","Un contrat d'assurance","Un type de garantie maritime"],correct:1,expl:"Piercing the corporate veil = levée du voile social. En principe, une compagnie maritime est une société distincte de ses dirigeants. Mais si : fraude délibérée (magic pipe ordonné par la direction), violation consciente de la loi, utilisation de la société comme écran. Les tribunaux peuvent tenir les dirigeants PERSONNELLEMENT responsables (prison + amende personnelle). Appliqué dans les affaires Princess Cruises, Carnival."},
    {q:"Qu'est-ce que la Convention OPRC (Oil Pollution Response and Cooperation) ?",opts:["Un règlement sur l'ORB","Convention internationale (1990) sur la préparation, la lutte et la coopération pour les déversements d'hydrocarbures — oblige les États à avoir des plans d'urgence","Une convention sur l'assurance pollution","Une convention sur les récompenses de sauvetage"],correct:1,expl:"OPRC 1990 = Convention sur la préparation, la lutte et la coopération en matière de pollution par les hydrocarbures. Oblige les États signataires à : établir des plans nationaux d'urgence, maintenir des équipements de lutte, coopérer internationalement lors de déversements majeurs. Base juridique des opérations de dépollution (type Erika 1999, Prestige 2002). Complémentaire à MARPOL."},
    {q:"Qu'est-ce que la règle de 'due diligence' applicable aux armateurs sous MARPOL ?",opts:["Une règle de navigation","Obligation de l'armateur de prendre toutes les mesures raisonnables pour éviter les violations MARPOL — peut réduire sa responsabilité","Une règle d'assurance","Une règle de chargement"],correct:1,expl:"Due diligence MARPOL = obligation de diligence raisonnable. Si l'armateur prouve qu'il a tout mis en œuvre (formation équipage, inspections régulières, procédures ISM rigoureuses), il peut atténuer sa responsabilité pour les infractions commises par l'équipage à son insu. Ne s'applique PAS aux magic pipes ordonnés par la direction (responsabilité objective + piercing the veil)."},
    {q:"Qu'est-ce que le 'Sulphur Cap 2020' et ses implications juridiques ?",opts:["Un règlement SOLAS","Règle MARPOL Annexe VI limitant la teneur en soufre à 0,5% mondial depuis le 01/01/2020 — violations = poursuites pénales dans les États parties","Un accord commercial","Une recommandation OMI"],correct:1,expl:"Sulphur Cap 2020 = MARPOL Annexe VI, Règle 14. En vigueur le 01/01/2020. Limite : 0,5% soufre mondial, 0,1% en ECA. Implications juridiques : États peuvent saisir des échantillons de carburant (BDN + prélèvement). Non-conformité = infraction MARPOL dans tous les États parties. USA : jusqu'à $40 000/jour d'amende. UE : amendes nationales + détention navire. Preuve légale = BDN conforme."},
    {q:"Qu'est-ce que l'immunité des témoins dans les affaires MARPOL aux USA ?",opts:["Une immunité diplomatique","Protection accordée par le tribunal fédéral à un témoin qui coopère avec l'enquête USCG — garantit qu'il ne sera pas poursuivi pour sa participation aux faits","Un privilège de droit du travail","Une protection syndicale"],correct:1,expl:"Immunité des témoins (witness immunity) = protection accordée par le US DOJ/USCG aux marins qui témoignent contre leur employeur. Garantit l'immunité de poursuite pour les actes auxquels le témoin a participé (ex : un mécanicien qui a opéré le magic pipe sous les ordres du chef). Condition : témoignage complet et véridique. Instrument essentiel pour briser l'omertà à bord."},
    {q:"Qu'est-ce que la 'probation agreement' signée par les compagnies condamnées pour violation MARPOL ?",opts:["Un contrat de renouvellement","Accord de probation judiciaire — la compagnie accepte des conditions strictes pendant une période (audits, rapports) sous peine d'amendes aggravées","Un contrat d'assurance","Un accord de formation"],correct:1,expl:"Probation agreement = accord de probation. Signé quand la compagnie plaide coupable en échange d'une réduction de peine. Conditions typiques : auditeur indépendant permanent (à frais de la compagnie), rapports trimestriels au tribunal, formation renforcée équipage, ligne téléphonique confidentielle pour signalements. Violation de la probation = aggravation immédiate. Princess Cruises a violé sa probation 2016 → aggravation 2019."},
    {q:"Quelle est la distinction entre 'déversement accidentel' et 'déversement délibéré' en droit MARPOL ?",opts:["Aucune distinction juridique","Déversement accidentel = responsabilité civile (assurance P&I) · Déversement délibéré = responsabilité pénale + amende + prison","Déversement délibéré = plus faible pénalité","Seul le déversement accidentel est couvert par MARPOL"],correct:1,expl:"Distinction fondamentale : Déversement ACCIDENTEL = peut être exonéré sous conditions MARPOL (Annexe I, Règle 4) : force majeure, mesures raisonnables prises, notification immédiate. Couvert par assurance P&I. Déversement DÉLIBÉRÉ = aucune exonération possible + responsabilité pénale. Magic pipe = toujours délibéré → prison. La notification tardive d'un déversement accidentel peut transformer la qualification en 'délibéré'."},
    {q:"Qu'est-ce que le programme EMSA (European Maritime Safety Agency) de surveillance par satellite ?",opts:["Un programme de formation maritime","Surveillance satellitaire des navires en Europe pour détecter les déversements d'hydrocarbures en mer — images satellites + AIS — preuves juridiques admissibles","Un programme de cartographie","Un programme d'aide aux naufragés"],correct:1,expl:"EMSA CleanSeaNet = programme de surveillance satellitaire des mers européennes. Utilise satellites radar (SAR) pour détecter les nappes d'hydrocarbures. Croise avec données AIS pour identifier le navire responsable. Images = preuves admissibles devant les tribunaux européens. Détection de milliers de déversements depuis 2007. Base de poursuites judiciaires dans plusieurs États membres UE."},
  ],
  en:[
    {q:"What is the 'right of hot pursuit' in maritime law?",opts:["A hunting right","Right of a coastal state to pursue a foreign vessel onto the high seas that has violated its laws in its waters — must be immediate and continuous","A commercial maritime right","A type of judicial procedure"],correct:1,expl:"Right of hot pursuit = UNCLOS Article 111. The coastal state can pursue a foreign vessel onto the high seas if: pursuit begins in its waters (territorial, EEZ, continental shelf), it is immediate and continuous, and ceases if the vessel enters third-state waters. Key: CONTINUITY of the pursuit."},
    {q:"What is the IOPC (International Oil Pollution Compensation) Fund?",opts:["A vessel insurance fund","International fund to compensate maritime oil pollution victims — funded by oil importers","An IMO fund for shipowners","A maritime research fund"],correct:1,expl:"IOPC Fund = International Oil Pollution Compensation Fund. Created by 1971 Convention, revised 1992. Compensates coastal states and individuals affected by spills. Funded by contributions from oil importers (not shipowners). Compensation ceiling: approximately $1.1 billion. Complementary to CLC Convention."},
    {q:"What is the CLC (Civil Liability Convention)?",opts:["A crew convention","Convention on civil liability of vessel owner for oil pollution — strict liability + mandatory P&I insurance","A maritime labour convention","A wreck convention"],correct:1,expl:"CLC = Convention on Civil Liability for Oil Pollution Damage (1969, revised 1992). STRICT liability of owner (no need to prove fault). Mandatory P&I insurance (Certificate of Insurance). Liability ceiling based on tonnage. Complemented by IOPC Fund for damages exceeding the ceiling."},
    {q:"What is a 'P&I Club' (Protection and Indemnity) in maritime law?",opts:["A pleasure sailing club","Maritime insurance mutual covering vessel civil liability: pollution, third-party damages, crew abandonment","A type of naval certification","A shipowners' union"],correct:1,expl:"P&I Club = Protection and Indemnity Club. Maritime insurance mutual created by shipowners in the 19th century. Covers: pollution liability (MARPOL/CLC), third-party damage, crew abandonment (MLC), wage claims, salvage. The 13 P&I clubs of the International Group cover 90% of the world fleet. CLC Certificate = issued by the P&I Club."},
    {q:"What is 'strict liability' in maritime pollution law?",opts:["Liability based on proven fault","Liability engaged without having to prove the owner's fault — only need to prove damage and causal link to vessel","Shared liability between shipowners","Only criminal liability"],correct:1,expl:"Strict liability = liability without fault. In maritime pollution law (CLC, OPRC), it is sufficient to prove: 1) that pollution damage occurred, 2) that the identified vessel is the source. No need to prove negligence or fault of the owner. Exception: force majeure (war, exceptional natural phenomenon). Guarantees rapid compensation for victims."},
    {q:"What is the difference between a MARPOL violation and a criminal offense?",opts:["No difference","MARPOL violation = administrative (fine) · Criminal offense = intentional or grossly negligent (prison possible)","MARPOL violation = more serious than criminal offense","Only criminal offenses concern seafarers"],correct:1,expl:"Key distinction: MARPOL violation = can be administrative (PSC fine, vessel detention). Criminal offense = when there is intent to defraud (magic pipe, false ORB) or gross negligence (non-notification of spill). USA: false ORB = federal crime (18 USC §1505) → prison. France/EU: deliberate discharge = maritime crime → prison. Falsification of records transforms a violation into a crime."},
    {q:"What is 'universal jurisdiction' applied to MARPOL?",opts:["IMO can prosecute any vessel","Some states extend their jurisdiction to MARPOL violations committed anywhere in the world — based on effects","COLREG applies everywhere","Each state has the same right"],correct:1,expl:"Universal jurisdiction applied to MARPOL = some states (particularly USA) extend criminal prosecution to violations committed on the high seas by foreign vessels if effects are felt in their waters or if the vessel calls at their ports. Based on the 'effects doctrine'. Foundation of USCG jurisprudence against foreign companies."},
    {q:"What is 'piercing the corporate veil' in maritime law?",opts:["A type of audit","Possibility for courts to disregard a company's legal personality to hold its directors personally liable — in case of deliberate fraud","An insurance contract","A type of maritime guarantee"],correct:1,expl:"Piercing the corporate veil = disregarding corporate legal personality. In principle, a maritime company is separate from its directors. But if: deliberate fraud (magic pipe ordered by management), conscious violation of law, use of company as a screen. Courts can hold directors PERSONALLY liable (prison + personal fine). Applied in Princess Cruises, Carnival cases."},
    {q:"What is the OPRC (Oil Pollution Response and Cooperation) Convention?",opts:["An ORB regulation","International convention (1990) on preparedness, response and cooperation for oil spills — obliges states to have emergency plans","A pollution insurance convention","A salvage reward convention"],correct:1,expl:"OPRC 1990 = Convention on Oil Pollution Preparedness, Response and Cooperation. Obliges signatory states to: establish national emergency plans, maintain response equipment, cooperate internationally during major spills. Legal basis for clean-up operations (Erika 1999, Prestige 2002). Complementary to MARPOL."},
    {q:"What is the 'due diligence' rule applicable to shipowners under MARPOL?",opts:["A navigation rule","Obligation of shipowner to take all reasonable measures to avoid MARPOL violations — can reduce liability","An insurance rule","A loading rule"],correct:1,expl:"Due diligence MARPOL = reasonable diligence obligation. If the shipowner proves they took all steps (crew training, regular inspections, rigorous ISM procedures), they may mitigate liability for violations committed by crew without their knowledge. Does NOT apply to magic pipes ordered by management (strict liability + piercing the veil)."},
    {q:"What is the 'Sulphur Cap 2020' and its legal implications?",opts:["A SOLAS regulation","MARPOL Annex VI rule limiting sulfur content to 0.5% globally since 01/01/2020 — violations = criminal prosecution in party states","A commercial agreement","An IMO recommendation"],correct:1,expl:"Sulphur Cap 2020 = MARPOL Annex VI, Rule 14. In force 01/01/2020. Limit: 0.5% global sulfur, 0.1% in ECA. Legal implications: states can take fuel samples (BDN + sampling). Non-compliance = MARPOL violation in all party states. USA: up to $40,000/day fine. EU: national fines + vessel detention. Legal proof = compliant BDN."},
    {q:"What is witness immunity in US MARPOL cases?",opts:["Diplomatic immunity","Protection granted by federal court to a witness cooperating with USCG investigation — guarantees no prosecution for participation in the acts","A labor law privilege","A union protection"],correct:1,expl:"Witness immunity = protection granted by US DOJ/USCG to seafarers who testify against their employer. Guarantees immunity from prosecution for acts the witness participated in (e.g. an engineer who operated the magic pipe under orders from the chief). Condition: complete and truthful testimony. Essential instrument for breaking the code of silence on board."},
    {q:"What is the 'probation agreement' signed by companies convicted of MARPOL violations?",opts:["A renewal contract","Judicial probation agreement — company accepts strict conditions for a period (audits, reports) under penalty of aggravated fines","An insurance contract","A training agreement"],correct:1,expl:"Probation agreement = judicial probation. Signed when company pleads guilty in exchange for reduced sentence. Typical conditions: permanent independent auditor (at company's expense), quarterly court reports, enhanced crew training, confidential reporting hotline. Probation violation = immediate aggravation. Princess Cruises violated 2016 probation → aggravation 2019."},
    {q:"What is the distinction between 'accidental discharge' and 'deliberate discharge' under MARPOL law?",opts:["No legal distinction","Accidental discharge = civil liability (P&I insurance) · Deliberate discharge = criminal liability + fine + prison","Deliberate discharge = lower penalty","Only accidental discharge is covered by MARPOL"],correct:1,expl:"Fundamental distinction: ACCIDENTAL discharge = may be exempted under MARPOL conditions (Annex I, Rule 4): force majeure, reasonable measures taken, immediate notification. Covered by P&I insurance. DELIBERATE discharge = no exemption possible + criminal liability. Magic pipe = always deliberate → prison. Late notification of an accidental discharge can reclassify it as 'deliberate'."},
    {q:"What is the EMSA satellite surveillance program for maritime pollution?",opts:["A maritime training program","Satellite surveillance of European vessels to detect oil spills at sea — satellite images + AIS — legally admissible evidence","A mapping program","An aid program for shipwrecked persons"],correct:1,expl:"EMSA CleanSeaNet = satellite surveillance program of European seas. Uses radar satellites (SAR) to detect oil slicks. Cross-references with AIS data to identify the responsible vessel. Images = legally admissible evidence in European courts. Detection of thousands of discharges since 2007. Basis for legal proceedings in several EU member states."},
  ],
  es:[
    {q:"¿Qué es el 'derecho de persecución' (hot pursuit) en derecho marítimo?",opts:["Un derecho de caza","Derecho de un Estado ribereño a perseguir en alta mar a un buque extranjero que ha violado sus leyes en sus aguas — debe ser inmediato y continuo","Un derecho comercial marítimo","Un tipo de procedimiento judicial"],correct:1,expl:"Derecho de persecución (hot pursuit) = CONVEMAR Artículo 111. El Estado ribereño puede perseguir a un buque extranjero hasta alta mar si: la persecución comienza en sus aguas, es inmediata y continua, y cesa si el buque entra en aguas de un tercer Estado. Clave: CONTINUIDAD de la persecución."},
    {q:"¿Qué es el Fondo IOPC (Fondo Internacional de Indemnización de Daños debidos a la Contaminación por Hidrocarburos)?",opts:["Un fondo de seguros de buques","Fondo internacional para indemnizar a las víctimas de contaminación por petróleo marítima — alimentado por los importadores de petróleo","Un fondo de la OMI para los armadores","Un fondo de investigación marítima"],correct:1,expl:"Fondo IOPC = Fondo Internacional de Indemnización de Daños debidos a la Contaminación por Hidrocarburos. Creado por el Convenio de 1971, revisado en 1992. Indemniza a los Estados ribereños y particulares afectados por derrames. Alimentado por aportaciones de los importadores de petróleo. Techo de indemnización: aproximadamente $1.100 millones. Complementario al Convenio CLC."},
    {q:"¿Qué es el Convenio CLC (Responsabilidad Civil)?",opts:["Un convenio sobre las tripulaciones","Convenio sobre la responsabilidad civil del propietario del buque por contaminación por hidrocarburos — responsabilidad objetiva + seguro P&I obligatorio","Un convenio de trabajo marítimo","Un convenio sobre pecios"],correct:1,expl:"CLC = Convenio sobre responsabilidad civil por daños debidos a la contaminación por hidrocarburos (1969, revisado 1992). Responsabilidad OBJETIVA del propietario (sin necesidad de probar la culpa). Seguro P&I obligatorio (Certificado de seguro). Techo de responsabilidad según tonelaje. Complementado por el Fondo IOPC para daños que superen el techo."},
    {q:"¿Qué es un 'club P&I' (Protección e Indemnización) en derecho marítimo?",opts:["Un club de navegación de recreo","Mutua de seguros marítimos que cubre la responsabilidad civil del buque: contaminación, daños a terceros, abandono de tripulación","Un tipo de certificación naval","Un sindicato de armadores"],correct:1,expl:"Club P&I = Club de Protección e Indemnización. Mutua de seguros marítimos creada por los armadores en el siglo XIX. Cubre: responsabilidad por contaminación (MARPOL/CLC), daños a terceros, abandono de tripulación (MLC), reclamaciones salariales, salvamento. Los 13 clubes P&I del International Group cubren el 90% de la flota mundial."},
    {q:"¿Qué es la responsabilidad 'objetiva' en derecho marítimo de la contaminación?",opts:["Una responsabilidad basada en la culpa probada","Responsabilidad que se exige sin necesidad de probar la culpa del propietario — basta con probar el daño y el nexo causal con el buque","Una responsabilidad compartida entre armadores","Una responsabilidad únicamente penal"],correct:1,expl:"Responsabilidad objetiva (strict liability) = responsabilidad sin culpa. En materia de contaminación marítima (CLC, OPRC), basta con probar: 1) que hubo daño por contaminación, 2) que el buque identificado es la fuente. No es necesario probar la negligencia o la culpa del propietario. Excepción: fuerza mayor. Garantiza una indemnización rápida a las víctimas."},
    {q:"¿Cuál es la diferencia entre infracción MARPOL y delito penal?",opts:["Ninguna diferencia","Infracción MARPOL = administrativa (multa) · Delito penal = infracción intencional o por negligencia grave (posible prisión)","Infracción MARPOL = más grave que delito penal","Solo los delitos penales afectan a los marineros"],correct:1,expl:"Distinción clave: Infracción MARPOL = puede ser administrativa (multa PSC, inmovilización buque). Delito penal = cuando hay intención de defraudar (magic pipe, ORB falso) o negligencia grave. EE.UU.: ORB falso = delito federal (18 USC §1505) → prisión. Francia/UE: vertido deliberado = delito marítimo → prisión. La falsificación de los registros convierte una infracción en delito."},
    {q:"¿Qué es la 'jurisdicción universal' aplicada a MARPOL?",opts:["La OMI puede enjuiciar cualquier buque","Algunos Estados extienden su jurisdicción a las infracciones MARPOL cometidas en cualquier lugar del mundo — basada en los efectos","COLREG se aplica en todas partes","Cada Estado tiene el mismo derecho"],correct:1,expl:"Jurisdicción universal aplicada a MARPOL = algunos Estados (especialmente EE.UU.) extienden sus acciones penales a las infracciones cometidas en alta mar por buques extranjeros si los efectos se sienten en sus aguas o si el buque toca sus puertos. Basada en la doctrina de los 'efectos'. Fundamento de la jurisprudencia USCG contra compañías extranjeras."},
    {q:"¿Qué es el 'levantamiento del velo societario' en derecho marítimo?",opts:["Un tipo de auditoría","Posibilidad de los tribunales de ignorar la personalidad jurídica de una sociedad para hacer personalmente responsables a sus directivos — en caso de fraude deliberado","Un contrato de seguro","Un tipo de garantía marítima"],correct:1,expl:"Levantamiento del velo societario = ignorar la personalidad jurídica de la sociedad. En principio, una compañía marítima es una entidad distinta de sus directivos. Pero si hay fraude deliberado (magic pipe ordenado por la dirección), uso de la sociedad como pantalla. Los tribunales pueden hacer a los directivos PERSONALMENTE responsables. Aplicado en los casos Princess Cruises, Carnival."},
    {q:"¿Qué es el Convenio OPRC?",opts:["Un reglamento sobre el ORB","Convenio internacional (1990) sobre la preparación, la lucha y la cooperación para los derrames de hidrocarburos — obliga a los Estados a tener planes de emergencia","Un convenio sobre el seguro de contaminación","Un convenio sobre las recompensas de salvamento"],correct:1,expl:"OPRC 1990 = Convenio sobre Preparación, Lucha y Cooperación en materia de Contaminación por Hidrocarburos. Obliga a los Estados signatarios a: establecer planes nacionales de emergencia, mantener equipos de lucha, cooperar internacionalmente en grandes derrames. Base jurídica de las operaciones de descontaminación (Erika 1999, Prestige 2002). Complementario a MARPOL."},
    {q:"¿Qué es la regla de 'due diligence' aplicable a los armadores según MARPOL?",opts:["Una regla de navegación","Obligación del armador de tomar todas las medidas razonables para evitar las infracciones MARPOL — puede reducir su responsabilidad","Una regla de seguros","Una regla de carga"],correct:1,expl:"Due diligence MARPOL = obligación de diligencia razonable. Si el armador prueba que tomó todas las medidas (formación tripulación, inspecciones regulares, procedimientos ISM rigurosos), puede mitigar su responsabilidad por las infracciones cometidas por la tripulación sin su conocimiento. No se aplica a los magic pipes ordenados por la dirección."},
    {q:"¿Qué es el 'Sulphur Cap 2020' y sus implicaciones jurídicas?",opts:["Un reglamento SOLAS","Norma MARPOL Anexo VI que limita el contenido de azufre al 0,5% mundial desde el 01/01/2020 — infracciones = acciones penales en los Estados parte","Un acuerdo comercial","Una recomendación de la OMI"],correct:1,expl:"Sulphur Cap 2020 = MARPOL Anexo VI, Regla 14. En vigor el 01/01/2020. Límite: 0,5% azufre mundial, 0,1% en ECA. Implicaciones jurídicas: los Estados pueden tomar muestras de combustible (BDN + muestreo). Incumplimiento = infracción MARPOL en todos los Estados parte. EE.UU.: hasta $40.000/día de multa."},
    {q:"¿Qué es la inmunidad de testigos en los casos MARPOL en EE.UU.?",opts:["Una inmunidad diplomática","Protección concedida por el tribunal federal a un testigo que coopera con la investigación USCG — garantiza que no será procesado por su participación en los hechos","Un privilegio de derecho laboral","Una protección sindical"],correct:1,expl:"Inmunidad de testigos = protección concedida por el DOJ/USCG de EE.UU. a los marineros que declaran contra su empleador. Garantiza la inmunidad de enjuiciamiento por los actos en los que participó el testigo. Condición: testimonio completo y veraz. Instrumento esencial para romper el silencio a bordo."},
    {q:"¿Qué es el 'acuerdo de libertad condicional' firmado por las compañías condenadas por infracción MARPOL?",opts:["Un contrato de renovación","Acuerdo de libertad condicional judicial — la compañía acepta condiciones estrictas durante un período (auditorías, informes) bajo pena de multas agravadas","Un contrato de seguros","Un acuerdo de formación"],correct:1,expl:"Acuerdo de libertad condicional = firmado cuando la compañía se declara culpable a cambio de una reducción de pena. Condiciones típicas: auditor independiente permanente, informes trimestrales al tribunal, formación reforzada de la tripulación, línea telefónica confidencial para denuncias. Violación de la libertad condicional = agravamiento inmediato."},
    {q:"¿Cuál es la distinción entre 'vertido accidental' y 'vertido deliberado' en derecho MARPOL?",opts:["Ninguna distinción jurídica","Vertido accidental = responsabilidad civil (seguro P&I) · Vertido deliberado = responsabilidad penal + multa + prisión","Vertido deliberado = menor penalidad","Solo el vertido accidental está cubierto por MARPOL"],correct:1,expl:"Distinción fundamental: Vertido ACCIDENTAL = puede exonerarse bajo condiciones MARPOL (Anexo I, Regla 4): fuerza mayor, medidas razonables tomadas, notificación inmediata. Cubierto por seguro P&I. Vertido DELIBERADO = ninguna exoneración posible + responsabilidad penal. Magic pipe = siempre deliberado → prisión."},
    {q:"¿Qué es el programa de vigilancia por satélite EMSA para la contaminación marítima?",opts:["Un programa de formación marítima","Vigilancia por satélite de los buques en Europa para detectar derrames de hidrocarburos en el mar — imágenes de satélite + AIS — pruebas jurídicamente admisibles","Un programa de cartografía","Un programa de ayuda a náufragos"],correct:1,expl:"EMSA CleanSeaNet = programa de vigilancia satelital de los mares europeos. Utiliza satélites radar (SAR) para detectar manchas de hidrocarburos. Cruza con datos AIS para identificar el buque responsable. Imágenes = pruebas admisibles ante los tribunales europeos. Detección de miles de vertidos desde 2007."},
  ],
  pt:[
    {q:"O que é o 'direito de perseguição' (hot pursuit) no direito marítimo?",opts:["Um direito de caça","Direito de um Estado costeiro perseguir em alto mar um navio estrangeiro que violou as suas leis nas suas águas — deve ser imediato e contínuo","Um direito comercial marítimo","Um tipo de procedimento judicial"],correct:1,expl:"Direito de perseguição (hot pursuit) = UNCLOS Artigo 111. O Estado costeiro pode perseguir um navio estrangeiro até ao alto mar se: a perseguição começa nas suas águas, é imediata e contínua, e cessa se o navio entrar nas águas de um terceiro Estado. Chave: CONTINUIDADE da perseguição."},
    {q:"O que é o Fundo IOPC?",opts:["Um fundo de seguros de navios","Fundo internacional para indemnizar as vítimas de poluição marítima por petróleo — alimentado pelos importadores de petróleo","Um fundo da IMO para armadores","Um fundo de investigação marítima"],correct:1,expl:"Fundo IOPC = Fundo Internacional de Indemnização de Danos por Poluição de Hidrocarbonetos. Criado pela Convenção de 1971, revisto em 1992. Indemniza estados costeiros e particulares afetados por derrames. Alimentado por contribuições dos importadores de petróleo. Teto de indemnização: aproximadamente $1,1 mil milhões."},
    {q:"O que é a Convenção CLC?",opts:["Uma convenção sobre tripulações","Convenção sobre a responsabilidade civil do proprietário do navio por poluição por hidrocarbonetos — responsabilidade objetiva + seguro P&I obrigatório","Uma convenção de trabalho marítimo","Uma convenção sobre destroços"],correct:1,expl:"CLC = Convenção sobre Responsabilidade Civil por Danos devidos à Poluição por Hidrocarbonetos (1969, revista 1992). Responsabilidade OBJETIVA do proprietário (sem necessidade de provar culpa). Seguro P&I obrigatório (Certificado de Seguro). Teto de responsabilidade segundo tonelagem."},
    {q:"O que é um 'clube P&I' no direito marítimo?",opts:["Um clube de navegação de recreio","Mútua de seguros marítimos que cobre a responsabilidade civil do navio: poluição, danos a terceiros, abandono de tripulação","Um tipo de certificação naval","Um sindicato de armadores"],correct:1,expl:"P&I Club = Clube de Proteção e Indemnização. Mútua de seguros marítimos criada pelos armadores no século XIX. Cobre: responsabilidade por poluição (MARPOL/CLC), danos a terceiros, abandono de tripulação (MLC), reclamações salariais, salvamento. Os 13 clubes do International Group cobrem 90% da frota mundial."},
    {q:"O que é a responsabilidade 'objetiva' no direito marítimo da poluição?",opts:["Uma responsabilidade baseada em culpa provada","Responsabilidade exigida sem necessidade de provar a culpa do proprietário — basta provar o dano e o nexo causal com o navio","Uma responsabilidade partilhada entre armadores","Uma responsabilidade apenas penal"],correct:1,expl:"Responsabilidade objetiva (strict liability) = responsabilidade sem culpa. Basta provar: 1) que houve dano por poluição, 2) que o navio identificado é a fonte. Não é necessário provar negligência ou culpa do proprietário. Exceção: força maior. Garante indemnização rápida às vítimas."},
    {q:"Qual é a diferença entre uma infração MARPOL e um crime penal?",opts:["Nenhuma diferença","Infração MARPOL = administrativa (multa) · Crime penal = infração intencional ou por negligência grave (possível prisão)","Infração MARPOL = mais grave que crime penal","Apenas os crimes penais dizem respeito aos marinheiros"],correct:1,expl:"Distinção fundamental: Infração MARPOL = pode ser administrativa (multa PSC, imobilização navio). Crime penal = quando há intenção de fraudar (magic pipe, ORB falso) ou negligência grave. EUA: ORB falso = crime federal (18 USC §1505) → prisão. França/UE: descarga deliberada = crime marítimo → prisão."},
    {q:"O que é a 'jurisdição universal' aplicada ao MARPOL?",opts:["A IMO pode processar qualquer navio","Alguns estados alargam a sua jurisdição a violações MARPOL cometidas em qualquer parte do mundo — baseada nos efeitos","O COLREG aplica-se em todo o lado","Cada estado tem o mesmo direito"],correct:1,expl:"Jurisdição universal aplicada ao MARPOL = alguns estados (especialmente EUA) alargam as suas ações penais a violações cometidas em alto mar por navios estrangeiros se os efeitos se fizerem sentir nas suas águas ou se o navio tocar os seus portos. Baseada na doutrina dos 'efeitos'. Fundamento da jurisprudência USCG contra companhias estrangeiras."},
    {q:"O que é o 'levantamento do véu societário' no direito marítimo?",opts:["Um tipo de auditoria","Possibilidade de os tribunais ignorarem a personalidade jurídica de uma sociedade para responsabilizar pessoalmente os seus dirigentes — em caso de fraude deliberada","Um contrato de seguro","Um tipo de garantia marítima"],correct:1,expl:"Levantamento do véu societário = ignorar a personalidade jurídica da sociedade. Se há fraude deliberada (magic pipe ordenado pela direção), uso da sociedade como ecrã. Os tribunais podem responsabilizar os dirigentes PESSOALMENTE (prisão + multa pessoal). Aplicado nos casos Princess Cruises, Carnival."},
    {q:"O que é a Convenção OPRC?",opts:["Um regulamento sobre o ORB","Convenção internacional (1990) sobre a preparação, resposta e cooperação para derrames de hidrocarbonetos — obriga os estados a ter planos de emergência","Uma convenção sobre seguros de poluição","Uma convenção sobre recompensas de salvamento"],correct:1,expl:"OPRC 1990 = Convenção sobre Preparação, Resposta e Cooperação em matéria de Poluição por Hidrocarbonetos. Obriga os estados signatários a: estabelecer planos de emergência nacionais, manter equipamentos de resposta, cooperar internacionalmente em grandes derrames. Base jurídica das operações de limpeza (Erika 1999, Prestige 2002)."},
    {q:"O que é a regra de 'due diligence' aplicável aos armadores segundo o MARPOL?",opts:["Uma regra de navegação","Obrigação do armador de tomar todas as medidas razoáveis para evitar violações MARPOL — pode reduzir a sua responsabilidade","Uma regra de seguros","Uma regra de carregamento"],correct:1,expl:"Due diligence MARPOL = obrigação de diligência razoável. Se o armador provar que tomou todas as medidas (formação tripulação, inspeções regulares, procedimentos ISM rigorosos), pode mitigar a responsabilidade por violações cometidas pela tripulação sem o seu conhecimento. Não se aplica a magic pipes ordenados pela direção."},
    {q:"O que é o 'Sulphur Cap 2020' e as suas implicações jurídicas?",opts:["Um regulamento SOLAS","Regra MARPOL Anexo VI que limita o teor de enxofre a 0,5% mundial desde 01/01/2020 — violações = ações penais nos estados parte","Um acordo comercial","Uma recomendação da IMO"],correct:1,expl:"Sulphur Cap 2020 = MARPOL Anexo VI, Regra 14. Em vigor 01/01/2020. Limite: 0,5% enxofre mundial, 0,1% em ECA. Implicações jurídicas: estados podem recolher amostras de combustível (BDN + amostragem). Não-conformidade = infração MARPOL em todos os estados parte. EUA: até $40.000/dia de multa."},
    {q:"O que é a imunidade das testemunhas nos casos MARPOL nos EUA?",opts:["Uma imunidade diplomática","Proteção concedida pelo tribunal federal a uma testemunha que coopera com a investigação USCG — garante que não será processada pela sua participação nos factos","Um privilégio do direito laboral","Uma proteção sindical"],correct:1,expl:"Imunidade das testemunhas = proteção concedida pelo DOJ/USCG dos EUA a marinheiros que testemunham contra o seu empregador. Garante imunidade de processo pelos atos em que a testemunha participou. Condição: testemunho completo e verdadeiro. Instrumento essencial para quebrar o silêncio a bordo."},
    {q:"O que é o 'acordo de liberdade condicional' assinado por companhias condenadas por violação MARPOL?",opts:["Um contrato de renovação","Acordo de liberdade condicional judicial — a companhia aceita condições estritas durante um período (auditorias, relatórios) sob pena de multas agravadas","Um contrato de seguros","Um acordo de formação"],correct:1,expl:"Acordo de liberdade condicional = assinado quando a companhia se declara culpada em troca de redução de pena. Condições típicas: auditor independente permanente, relatórios trimestrais ao tribunal, formação reforçada da tripulação, linha confidencial para denúncias. Violação da liberdade condicional = agravamento imediato."},
    {q:"Qual é a distinção entre 'descarga acidental' e 'descarga deliberada' no direito MARPOL?",opts:["Nenhuma distinção jurídica","Descarga acidental = responsabilidade civil (seguro P&I) · Descarga deliberada = responsabilidade penal + multa + prisão","Descarga deliberada = menor penalidade","Apenas a descarga acidental é coberta pelo MARPOL"],correct:1,expl:"Distinção fundamental: Descarga ACIDENTAL = pode ser isenta sob condições MARPOL (Anexo I, Regra 4): força maior, medidas razoáveis tomadas, notificação imediata. Coberta por seguro P&I. Descarga DELIBERADA = nenhuma isenção possível + responsabilidade penal. Magic pipe = sempre deliberado → prisão."},
    {q:"O que é o programa de vigilância por satélite da EMSA para poluição marítima?",opts:["Um programa de formação marítima","Vigilância por satélite de navios na Europa para detetar derrames de hidrocarbonetos no mar — imagens de satélite + AIS — provas juridicamente admissíveis","Um programa de cartografia","Um programa de ajuda a náufragos"],correct:1,expl:"EMSA CleanSeaNet = programa de vigilância satelital dos mares europeus. Utiliza satélites radar (SAR) para detetar manchas de hidrocarbonetos. Cruza com dados AIS para identificar o navio responsável. Imagens = provas admissíveis nos tribunais europeus. Deteção de milhares de derrames desde 2007."},
  ],
};

function QuestionBank({ lang }) {
  const [cur,setCur]=useState(0);const [sel,setSel]=useState(null);const [answered,setAnswered]=useState(false);const [score,setScore]=useState(0);const [done,setDone]=useState(false);
  const questions=BANK[lang]||BANK.fr;const q=questions[cur];const isOk=sel===q.correct;
  const pick=i=>{if(answered)return;setSel(i);setAnswered(true);if(i===q.correct)setScore(s=>s+1);};
  const next=()=>{if(cur<questions.length-1){setCur(c=>c+1);setSel(null);setAnswered(false);}else setDone(true);};
  if(done)return(<div style={{textAlign:"center",padding:"20px 0"}}><div style={{fontSize:48}}>{score>=12?"🏆":score>=8?"🎖️":"📚"}</div><div style={{fontFamily:"'Cinzel',serif",fontSize:20,color:C.white,margin:"8px 0 4px"}}>{score}/{questions.length}</div><div style={{fontSize:14,color:C.gold2}}>{Math.round(score/questions.length*100)}%</div></div>);
  return(<div>
    <div style={{display:"flex",justifyContent:"space-between",marginBottom:10}}><div style={{fontSize:10,color:C.muted}}>{cur+1}/{questions.length}</div><div style={{fontSize:12,color:C.gold2,fontWeight:700}}>✓ {score}</div></div>
    <div style={{height:3,background:"rgba(255,255,255,0.08)",borderRadius:3,marginBottom:12,overflow:"hidden"}}><div style={{height:"100%",width:`${(cur/questions.length)*100}%`,background:`linear-gradient(90deg,${C.red},${C.gold2})`}}/></div>
    <div style={{fontSize:13,fontWeight:700,color:C.white,lineHeight:1.5,marginBottom:12}}>{q.q}</div>
    <div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:10}}>
      {q.opts.map((opt,i)=>{let bg="rgba(255,255,255,0.05)",bd="rgba(255,255,255,0.1)";if(answered){if(i===q.correct){bg="rgba(30,138,74,0.2)";bd=C.green;}else if(i===sel){bg="rgba(192,57,43,0.2)";bd=C.red;}}return<button key={i} onClick={()=>pick(i)} style={{padding:"10px 12px",borderRadius:12,background:bg,border:`1.5px solid ${bd}`,color:C.muted,fontSize:12,textAlign:"left",cursor:answered?"default":"pointer",lineHeight:1.4}}>{opt}</button>;})}
    </div>
    {answered&&<><div style={{padding:"10px 12px",borderRadius:10,marginBottom:10,background:isOk?"rgba(30,138,74,0.12)":"rgba(192,57,43,0.1)",border:`1px solid ${isOk?C.green:C.red}44`,fontSize:11,color:C.white,lineHeight:1.6}}>{q.expl}</div>
    <button onClick={next} style={{width:"100%",padding:"11px 0",border:"none",borderRadius:12,background:`linear-gradient(135deg,${C.red},${C.gold2})`,fontFamily:"'Cinzel',serif",fontSize:12,fontWeight:700,letterSpacing:2,color:C.white,cursor:"pointer"}}>{cur<questions.length-1?(lang==="fr"?"SUIVANT →":lang==="en"?"NEXT →":lang==="es"?"SIGUIENTE →":"PRÓXIMO →"):(lang==="fr"?"TERMINER":lang==="en"?"FINISH":lang==="es"?"TERMINAR":"TERMINAR")}</button></>}
  </div>);
}

function Stars(){const s=Array.from({length:14},()=>({x:Math.random()*100,y:Math.random()*100,sz:Math.random()>0.7?2:1.5,dur:2+Math.random()*4,delay:Math.random()*6}));return(<><div style={{position:"fixed",inset:0,pointerEvents:"none",zIndex:0}}>{s.map((st,i)=><div key={i} style={{position:"absolute",left:`${st.x}%`,top:`${st.y}%`,width:st.sz,height:st.sz,borderRadius:"50%",background:"white",opacity:0,animation:`tw ${st.dur}s ease-in-out ${st.delay}s infinite`}}/>)}</div><style>{`@keyframes tw{0%,100%{opacity:0}50%{opacity:0.35}}@keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}@keyframes correctPop{0%{transform:scale(0.85)}60%{transform:scale(1.1)}100%{transform:scale(1)}}@keyframes wrongShake{0%,100%{transform:translateX(0)}25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}`}</style></>);}
function Card({children,style={}}){return<div style={{background:"rgba(13,31,60,0.75)",border:`1px solid ${C.border}`,borderRadius:18,padding:"16px",...style}}>{children}</div>;}
function GLine(){return<div style={{height:1,margin:"14px 0",background:`linear-gradient(90deg,transparent,${C.red}33,${C.gold2}33,transparent)`}}/>;}
function SL({icon,text,color}){return<div style={{display:"flex",alignItems:"center",gap:10,margin:"20px 0 12px"}}><span style={{fontSize:20}}>{icon}</span><div style={{fontFamily:"'Cinzel',serif",fontSize:12,fontWeight:700,color:color||C.gold,letterSpacing:2}}>{text}</div><div style={{flex:1,height:1,background:`linear-gradient(90deg,${color||C.gold}44,transparent)`}}/></div>;}

function QuizComp({questions,t,onComplete}){
  const [cur,setCur]=useState(0);const [sel,setSel]=useState(null);const [answered,setAnswered]=useState(false);const [score,setScore]=useState(0);const [answers,setAnswers]=useState([]);const [done,setDone]=useState(false);
  const q=questions[cur];const isOk=sel===q.correct;
  const pick=i=>{if(answered)return;setSel(i);setAnswered(true);if(i===q.correct)setScore(s=>s+1);setAnswers(a=>[...a,{i,ok:i===q.correct}]);};
  const next=()=>{if(cur<questions.length-1){setCur(c=>c+1);setSel(null);setAnswered(false);}else{setDone(true);onComplete(score+(isOk?1:0));}};
  if(done){const fs=score;const pct=Math.round(fs/questions.length*100);const xp=fs>=4?200:fs===3?120:60;return(<Card style={{textAlign:"center"}}><div style={{fontSize:52,marginBottom:8}}>{pct===100?"🏆":pct>=80?"🎖️":"📚"}</div><div style={{fontFamily:"'Cinzel',serif",fontSize:28,fontWeight:900,color:C.white,marginBottom:4}}>{fs}/{questions.length}</div><div style={{display:"inline-block",marginTop:8,padding:"6px 16px",borderRadius:20,background:"rgba(201,146,42,0.15)",border:`1px solid ${C.gold}44`,fontSize:14,color:C.gold2,fontWeight:700}}>+{xp} {t.xp} ⭐</div><GLine/><div style={{display:"flex",justifyContent:"center",gap:8,marginTop:8}}>{answers.map((a,i)=><div key={i} style={{width:32,height:32,borderRadius:"50%",background:a.ok?C.green:C.red,display:"flex",alignItems:"center",justifyContent:"center",fontSize:14,color:C.white}}>{a.ok?"✓":"✗"}</div>)}</div></Card>);}
  return(<Card style={{border:`1px solid ${C.red}33`}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}><div style={{fontSize:11,letterSpacing:3,color:C.red,fontFamily:"'Cinzel',serif"}}>{t.quiz}</div><div style={{fontSize:12,color:C.muted}}>{t.question} {cur+1} {t.ofQ} {questions.length}</div></div><div style={{display:"flex",gap:6,marginBottom:16}}>{questions.map((_,i)=><div key={i} style={{flex:1,height:3,borderRadius:3,background:i<cur?(answers[i]?.ok?C.green:C.red):i===cur?C.red:"rgba(255,255,255,0.1)"}}/>)}</div><div style={{fontSize:14,fontWeight:700,color:C.white,lineHeight:1.5,marginBottom:16}}>{q.q}</div><div style={{display:"flex",flexDirection:"column",gap:10,marginBottom:14}}>{q.opts.map((opt,i)=>{let bg="rgba(255,255,255,0.05)",bd="rgba(255,255,255,0.1)",anim="none";if(answered){if(i===q.correct){bg="rgba(30,138,74,0.2)";bd=C.green;anim="correctPop 0.4s ease";}else if(i===sel){bg="rgba(192,57,43,0.2)";bd=C.red;anim="wrongShake 0.4s ease";}}return<button key={i} onClick={()=>pick(i)} style={{padding:"12px 14px",borderRadius:14,background:bg,border:`1.5px solid ${bd}`,color:answered&&(i===q.correct||i===sel)?C.white:C.muted,fontSize:13,textAlign:"left",cursor:answered?"default":"pointer",animation:anim,display:"flex",alignItems:"center",gap:10,lineHeight:1.4}}><div style={{width:26,height:26,borderRadius:"50%",flexShrink:0,background:answered&&i===q.correct?C.green:answered&&i===sel?C.red:"rgba(255,255,255,0.1)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:12,fontWeight:700,color:C.white}}>{answered&&i===q.correct?"✓":answered&&i===sel?"✗":String.fromCharCode(65+i)}</div><span>{opt}</span></button>;})} </div>{answered&&<div style={{padding:"12px 14px",borderRadius:12,marginBottom:14,background:isOk?"rgba(30,138,74,0.12)":"rgba(192,57,43,0.1)",border:`1px solid ${isOk?C.green:C.red}44`,animation:"fadeUp 0.4s ease"}}><div style={{fontSize:12,fontWeight:700,marginBottom:4,color:isOk?C.green:C.red}}>{isOk?t.correct:t.wrong}</div><div style={{fontSize:11,color:C.muted,fontWeight:600,marginBottom:2}}>{t.expl}</div><div style={{fontSize:12,color:C.white,lineHeight:1.6}}>{q.expl}</div></div>}{answered&&<button onClick={next} style={{width:"100%",padding:"14px 0",border:"none",borderRadius:14,background:`linear-gradient(135deg,${C.red},${C.gold})`,fontFamily:"'Cinzel',serif",fontSize:13,fontWeight:700,letterSpacing:2,color:C.white,cursor:"pointer"}}>{cur<questions.length-1?t.next:t.finish}</button>}</Card>);
}

